<?php
declare(strict_types=1);
function auth_routes(App $a,string $path,array $b,string $method): ?array {
 if($path==='/status'&&$method==='GET')return [200,['setup'=>!$a->one('SELECT id FROM {{users}} LIMIT 1'),'runtime'=>'php-mysql']];
 if($path==='/setup'&&$method==='POST'){if($a->one('SELECT id FROM {{users}} LIMIT 1'))fail('Studio đã được khởi tạo.',409);$token=is_file($a->storage.'/setup-token')?trim(file_get_contents($a->storage.'/setup-token')):'';if(!$token||!is_string($b['token']??null)||!hash_equals($token,$b['token']))fail('Mã thiết lập không đúng.',403);$v=validate_employee(array_merge($b,['role'=>'admin','status'=>'active','monthly_salary'=>8000000]),true);$a->createEmployee($v,0);@unlink($a->storage.'/setup-token');return [201,['ok'=>true]];}
 if($path==='/login'&&$method==='POST'){$now=now_ms();$key=hash('sha256',$_SERVER['REMOTE_ADDR']??'');$attempt=$a->one('SELECT * FROM {{login_attempts}} WHERE ip_hash=?',[$key]);if(!$attempt||$attempt['until_time']<$now){$a->run('INSERT INTO {{login_attempts}} VALUES(?,0,?) ON DUPLICATE KEY UPDATE count=0,until_time=VALUES(until_time)',[$key,$now+900000]);$attempt=['count'=>0];}if($attempt['count']>=20)return [429,['error'=>'Thử quá nhiều lần. Vui lòng đợi 15 phút.']];$a->run('UPDATE {{login_attempts}} SET count=count+1 WHERE ip_hash=?',[$key]);$u=$a->one('SELECT * FROM {{users}} WHERE email=?',[strtolower(trim(is_string($b['email']??null)?$b['email']:''))]);$password=$b['password']??null;$valid=false;if($u&&is_string($password)&&strlen($password)<=128){$valid=password_verify($password,$u['password']);if(!$valid&&preg_match('/^([a-f0-9]{32}):([a-f0-9]{128})$/D',$u['password'],$legacy)&&function_exists('sodium_crypto_pwhash_scryptsalsa208sha256')){try{$valid=hash_equals(hex2bin($legacy[2]),sodium_crypto_pwhash_scryptsalsa208sha256(64,$password,$legacy[1],524288,16777216));}catch(Throwable){$valid=false;}}}if(!$u||$u['archived']||$u['status']==='inactive'||!$valid)return [401,['error'=>'Email hoặc mật khẩu không đúng.']];if(!str_starts_with($u['password'],'$')||password_needs_rehash($u['password'],PASSWORD_DEFAULT))$a->run('UPDATE {{users}} SET password=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$u['id']]);$token=bin2hex(random_bytes(32));$a->run('INSERT INTO {{sessions}} VALUES(?,?,?,?)',[hash('sha256',$token),$u['id'],$now+604800000,bin2hex(random_bytes(32))]);$a->run('DELETE FROM {{login_attempts}} WHERE ip_hash=?',[$key]);$a->cookie($token,time()+604800);return [200,['user'=>$a->safe($u)]];}
 return null;
}
function main_routes(App $a,string $path,array $b,string $method): ?array {
 if($path==='/logout'&&$method==='POST'){$a->run('DELETE FROM {{sessions}} WHERE token=?',[$a->session]);$a->cookie('',time()-3600);return [200,['ok'=>true]];}
 // Tự đổi mật khẩu từ avatar: cần mật khẩu hiện tại, sai 10 lần khóa 15 phút; đăng xuất thiết bị khác, giữ phiên đang dùng.
 if($path==='/me/password'&&$method==='POST'){$now=now_ms();$key=hash('sha256','password:'.$a->user['id']);$attempt=$a->one('SELECT * FROM {{login_attempts}} WHERE ip_hash=?',[$key]);if(!$attempt||$attempt['until_time']<$now){$a->run('INSERT INTO {{login_attempts}} VALUES(?,0,?) ON DUPLICATE KEY UPDATE count=0,until_time=VALUES(until_time)',[$key,$now+900000]);$attempt=['count'=>0];}if($attempt['count']>=10)return [429,['error'=>'Nhập sai mật khẩu hiện tại quá nhiều lần. Vui lòng đợi 15 phút.']];$current=$b['current_password']??null;$next=$b['new_password']??null;if(!is_string($current)||strlen($current)>128||!password_verify($current,$a->user['password'])){$a->run('UPDATE {{login_attempts}} SET count=count+1 WHERE ip_hash=?',[$key]);return [400,['error'=>'Mật khẩu hiện tại không đúng.']];}if(!is_string($next)||strlen($next)<10||strlen($next)>128)fail('Mật khẩu mới cần từ 10–128 ký tự.');if($next===$current)fail('Mật khẩu mới cần khác mật khẩu hiện tại.');$a->run('UPDATE {{users}} SET password=? WHERE id=?',[password_hash($next,PASSWORD_DEFAULT),$a->user['id']]);$a->run('DELETE FROM {{sessions}} WHERE user_id=? AND token<>?',[$a->user['id'],$a->session]);$a->run('DELETE FROM {{login_attempts}} WHERE ip_hash=?',[$key]);$a->audit($a->user['id'],'password_self');return [200,['ok'=>true]];}
 if($path==='/me'&&$method==='GET')return [200,['clientVersion'=>CLIENT_VERSION,'serverTime'=>now_ms(),'shifts'=>SHIFTS,'user'=>$a->safe($a->user),'csrf'=>$a->csrf,'expectedShifts'=>function_exists('expected_shifts')?expected_shifts($a,$a->user['id'],local_day(now_ms())):[],'studio'=>$a->one('SELECT * FROM {{settings}} WHERE id=1'),'events'=>array_reverse($a->events($a->user['id'])),'dailyTasks'=>function_exists('daily_tasks_today')?daily_tasks_today($a,$a->user['id']):[]]];
 if(preg_match('~^/events/(\d+)/photo$~D',$path,$m)&&$method==='GET'){$row=$a->one('SELECT user_id,photo_jpeg FROM {{events}} WHERE id=?',[(int)$m[1]]);if(!$row||!$row['photo_jpeg'])fail('Không có ảnh cho lượt chấm công này.',404);if($a->user['role']==='employee'&&$row['user_id']!==$a->user['id'])fail('Bạn không có quyền xem ảnh này.',403);header('Content-Type: image/jpeg');header('Content-Disposition: inline');echo $row['photo_jpeg'];exit;}
 if($path==='/history'&&$method==='GET'){$month=valid_month($_GET['month']??'');return [200,['events'=>array_reverse(array_values(array_filter($a->events($a->user['id']),fn($e)=>str_starts_with(local_day($e['time']),$month)||str_starts_with($e['work_date']??'',$month))))]];}
 if($path==='/attendance'&&$method==='POST'){if(!in_array($b['type']??'', ['in','out'],true))fail('Loại chấm công không hợp lệ.');if(function_exists('daily_tasks_block_checkout'))daily_tasks_block_checkout($a,$b);$time=now_ms();$id=$a->insertEvent(['time'=>$time,...$b,'time'=>$time],$a->user['id'],false);return [201,['ok'=>true,'time'=>$time,'type'=>$b['type'],'shift'=>$b['shift'],'id'=>$id]];}
 if($path==='/monthly'&&$method==='GET')return [200,$a->monthly($_GET['month']??'')];
 if($path==='/attendance-photos'&&$method==='GET'){$day=valid_day($_GET['date']??local_day(now_ms()));$page=filter_var($_GET['page']??1,FILTER_VALIDATE_INT);if(!$page||$page<1||$page>10000)fail('Trang ảnh không hợp lệ.');$params=[day_time($day),day_time($day)+86400000];$where='e.photo_jpeg IS NOT NULL AND e.time>=? AND e.time<?';if($a->user['role']==='employee'){$where.=' AND e.user_id=?';$params[]=$a->user['id'];}$total=(int)$a->scalar('SELECT COUNT(*) FROM {{events}} e WHERE '.$where,$params);$photos=$a->all('SELECT e.id,u.name,e.type,e.time,e.shift FROM {{events}} e JOIN {{users}} u ON u.id=e.user_id WHERE '.$where.' ORDER BY e.time DESC,e.id DESC LIMIT 60 OFFSET '.(($page-1)*60),$params);return [200,['photos'=>$photos,'total'=>$total,'page'=>$page]];}
 if($path==='/dashboard'&&$method==='GET'){$date=valid_day($_GET['date']??local_day(now_ms()));$people=$a->user['role']==='employee'?[$a->safe($a->user)]:$a->all("SELECT id,name,email,role FROM {{users}} WHERE archived=0 AND status!='inactive' ORDER BY name");$ids=array_column($people,'id');$all=array_values(array_filter($a->events(),fn($e)=>in_array($e['user_id'],$ids,true)));$daily=array_values(array_filter($all,fn($e)=>local_day($e['time'])===$date));$checked=[];$completed=0;foreach($daily as $e){if($e['type']==='in')$checked[$e['user_id']]=true;if($e['type']==='out'&&in_array($e['shift'],['day_first','day_second'],true))$completed++;}$shifts=[];foreach(SHIFTS as $s)$shifts[]=$s+['entries'=>count(array_filter($daily,fn($e)=>$e['shift']===$s['id']&&$e['type']==='in')),'exits'=>count(array_filter($daily,fn($e)=>$e['shift']===$s['id']&&$e['type']==='out'))];$ot=0;foreach($people as $p)if(array_filter(pairs(array_values(array_filter($all,fn($e)=>$e['user_id']===$p['id'])))['pending'],fn($e)=>$e['shift']==='ot'))$ot++;return [200,['date'=>$date,'otActive'=>$ot,'people'=>count($people),'checkedIn'=>count($checked),'completed'=>$completed,'shifts'=>$shifts,'payroll'=>array_values(array_filter($a->monthly(substr($date,0,7))['rows'],fn($p)=>in_array($p['id'],$ids,true)))]];}
 if($path==='/overtime'&&$method==='GET'){$month=valid_month($_GET['month']??'');$start=day_time($month.'-01');$end=strtotime($month.'-01T00:00:00+07:00 +1 month')*1000;$people=$a->user['role']==='employee'?[$a->safe($a->user)]:$a->all('SELECT id,name FROM {{users}}');$sessions=[];foreach($people as $p){$paired=pairs($a->events($p['id']));foreach($paired['pairs'] as $s)if($s['entry']['shift']==='ot'&&$s['end']>=$start&&$s['start']<$end)$sessions[]=ot_row($p,$s['entry'],$s['exit'],$s['start'],$s['end']);foreach($paired['pending'] as $e)if($e['shift']==='ot'&&$e['time']<$end&&now_ms()>=$start)$sessions[]=ot_row($p,$e,null,$e['time'],null);}usort($sessions,fn($x,$y)=>$y['start']<=>$x['start']);return [200,['sessions'=>$sessions]];}
 return null;
}
function ot_row(array $p,array $in,?array $out,int $start,?int $end): array {return ['user_id'=>$p['id'],'name'=>$p['name'],'start'=>$start,'end'=>$end,'in_source'=>$in['source'],'out_source'=>$out['source']??null,'in_reason'=>$in['reason'],'out_reason'=>$out['reason']??null,'in_recorded_by'=>$in['recorded_by_name'],'out_recorded_by'=>$out['recorded_by_name']??null,'in_event_id'=>$in['id'],'out_event_id'=>$out['id']??null,'in_photo'=>(bool)$in['has_photo'],'out_photo'=>(bool)($out['has_photo']??false),'confirmed_at'=>$in['ot_confirmed_at'],'work_date'=>$in['work_date'],'hours'=>$end!==null?round(($end-$start)/3600000,2):null];}
function management_routes(App $a,string $path,array $b,string $method): ?array {
 $a->requireManager();
 if($path==='/employees'&&$method==='GET'){booking_rates_seed($a);return [200,['users'=>$a->employees(($_GET['archived']??'')==='1')]];}
 if(in_array($path,['/employees','/users'],true)&&$method==='POST'){if($path==='/users')$a->requireAdmin();$v=validate_employee($path==='/users'?array_merge(['role'=>'employee','status'=>'active','monthly_salary'=>8000000],$b):$b,true);authorize_edit($a->user,null,$v);$id=$a->createEmployee($v,$a->user['id']);if(!empty($v['booking_rate']))booking_rate_save($a,$id,$v['booking_rate']);return [201,['id'=>$id]];}
 if(preg_match('~^/employees/(\d+)(?:/(delete|restore))?$~D',$path,$m)&&$method==='POST'){$id=(int)$m[1];$action=$m[2]??'';$target=$a->one('SELECT * FROM {{users}} WHERE id=?',[$id]);if(!$target)fail('Không tìm thấy nhân viên.',404);$change=$action==='delete'?['archived'=>true,'status'=>'inactive']:($action==='restore'?['status'=>'inactive']:validate_employee($b));authorize_edit($a->user,$target,$change);if(!$action&&$target['archived'])fail('Khôi phục hồ sơ trước khi chỉnh sửa.',409);if($action){$a->run('UPDATE {{users}} SET archived=?,status=\'inactive\' WHERE id=?',[$action==='delete'?1:0,$id]);$a->run('DELETE FROM {{sessions}} WHERE user_id=?',[$id]);$a->audit($id,$action==='delete'?'archive':'restore');}else{$fields=['name','email','role','status',...PROFILE_FIELDS];$a->run('UPDATE {{users}} SET '.implode(',',array_map(fn($f)=>$f.'=?',$fields)).' WHERE id=?',[...array_map(fn($f)=>$change[$f],$fields),$id]);$a->run('INSERT INTO {{salaries}} VALUES(?,?) ON DUPLICATE KEY UPDATE monthly_salary=VALUES(monthly_salary)',[$id,$change['monthly_salary']]);if(array_key_exists('booking_rate',$change))booking_rate_save($a,$id,$change['booking_rate']);if(!empty($change['password']))$a->run('UPDATE {{users}} SET password=? WHERE id=?',[password_hash($change['password'],PASSWORD_DEFAULT),$id]);if(!empty($change['password'])||$change['status']==='inactive'||$change['role']!==$target['role'])$a->run('DELETE FROM {{sessions}} WHERE user_id=?',[$id]);$a->audit($id,'update');}return [200,['ok'=>true,'archived'=>$action==='delete']];}
 if($path==='/users'&&$method==='GET')return [200,['users'=>$a->all("SELECT u.id,u.name,u.email,u.role,COALESCE(s.monthly_salary,8000000) monthly_salary FROM {{users}} u LEFT JOIN {{salaries}} s ON s.user_id=u.id WHERE u.archived=0 AND u.status!='inactive' ORDER BY u.name")]];
 if($path==='/wages'&&$method==='POST'){if(!is_int($b['user_id']??null)||!is_int($b['monthly_salary']??null)||$b['monthly_salary']<0||$b['monthly_salary']>1000000000)fail('Lương cứng không hợp lệ.');$a->target($b['user_id']);$a->run('INSERT INTO {{salaries}} VALUES(?,?) ON DUPLICATE KEY UPDATE monthly_salary=VALUES(monthly_salary)',[$b['user_id'],$b['monthly_salary']]);$a->audit($b['user_id'],'salary');return [200,['ok'=>true]];}
 if($path==='/role'&&$method==='POST'){$a->requireAdmin();if(!is_int($b['user_id']??null)||!in_array($b['role']??'',['admin','manager','employee'],true))fail('Phân quyền không hợp lệ.');$target=$a->target($b['user_id']);if($target['id']===$a->user['id'])fail('Bạn không thể tự thay đổi quyền.');$a->run('UPDATE {{users}} SET role=? WHERE id=?',[$b['role'],$target['id']]);$a->run('DELETE FROM {{sessions}} WHERE user_id=?',[$target['id']]);$a->audit($target['id'],'role');return [200,['ok'=>true]];}
 if($path==='/settings'&&$method==='POST'){foreach(['latitude','longitude','radius'] as $f)if(!is_numeric($b[$f]??null)||!is_finite((float)$b[$f]))fail('Tọa độ hoặc bán kính không hợp lệ.');if(abs($b['latitude'])>90||abs($b['longitude'])>180||$b['radius']<20||$b['radius']>1000)fail('Bán kính từ 20–1.000 m.');$labels=[];foreach(['location_label','province_code','ward_code','address'] as $f){$labels[$f]=$b[$f]??'';if(!is_string($labels[$f])||!preg_match('//u',$labels[$f])||text_length($labels[$f])>(in_array($f,['province_code','ward_code'],true)?150:500))fail('Địa chỉ studio không hợp lệ.');}$a->run('INSERT INTO {{settings}} VALUES(1,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE latitude=VALUES(latitude),longitude=VALUES(longitude),radius=VALUES(radius),location_label=VALUES(location_label),province_code=VALUES(province_code),ward_code=VALUES(ward_code),address=VALUES(address)',[$b['latitude'],$b['longitude'],(int)round($b['radius']),...array_values($labels)]);return [200,['ok'=>true]];}
 if($path==='/commissions'&&$method==='GET')return [200,['rows'=>$a->all('SELECT c.*,u.name FROM {{commissions}} c JOIN {{users}} u ON u.id=c.user_id ORDER BY served_at DESC LIMIT 200')]];
 if($path==='/commissions'&&$method==='POST'){if(!is_string($b['id']??null)||!preg_match('/^[a-f0-9-]{36}$/iD',$b['id'])||!is_int($b['user_id']??null)||!is_int($b['customers']??null)||$b['customers']<1||$b['customers']>1000||!is_int($b['served_at']??null)||$b['served_at']>now_ms()||$b['served_at']<1577836800000)fail('Nhân viên, số khách hoặc thời điểm không hợp lệ.');$a->target($b['user_id']);$a->assertOpen($b['served_at']);if($a->one('SELECT id FROM {{commissions}} WHERE id=?',[$b['id']]))fail('Lượt khách đã được ghi nhận.',409);$ot=has_ot($a->events($b['user_id']),$b['served_at'],now_ms());$hour=(int)gmdate('G',(int)floor($b['served_at']/1000)+25200);if($hour<9&&!$ot)fail('Ngoài giờ làm và không có lượt OT phù hợp.');$rate=$hour>=19||$ot?30000:15000;if($rate===30000&&!$ot)fail('Chưa có lượt chấm OT bao phủ thời điểm phục vụ.',409);$a->run('INSERT INTO {{commissions}} VALUES(?,?,?,?,?,?,?)',[$b['id'],$b['user_id'],$b['served_at'],$b['customers'],$rate,$a->user['id'],now_ms()]);return [201,['ok'=>true,'rate'=>$rate]];}
 if($path==='/report'&&$method==='GET'){$month=valid_month($_GET['month']??substr(local_day(now_ms()),0,7));return [200,['events'=>array_reverse(array_values(array_filter($a->events(),fn($e)=>str_starts_with(local_day($e['time']),$month)||str_starts_with($e['work_date']??'',$month))))]];}
 // Chấm hộ cả ca: ghi lượt vào và lượt ra trong một lần, cùng lý do; không cần nhân viên checkin/checkout.
 if($path==='/attendance/manual-shift'&&$method==='POST'){if(!is_int($b['user_id']??null))fail('Chọn nhân viên.');$a->target($b['user_id']);if(!in_array($b['shift']??'',['day_first','day_second'],true))fail('Chọn Ca 1 hoặc Ca 2.');$in=$b['in_time']??null;$out=$b['out_time']??null;if(!is_int($in)||!is_int($out)||$out<=$in)fail('Giờ ra phải sau giờ vào.');if(local_day($in)!==local_day($out))fail('Giờ vào và giờ ra phải cùng một ngày.');if($out>now_ms())fail('Ca chưa kết thúc. Chấm hộ cả ca sau giờ ra, hoặc chấm hộ riêng lượt vào.');if($a->one('SELECT id FROM {{events}} WHERE user_id=? AND shift=? AND work_date=?',[$b['user_id'],$b['shift'],local_day($in)]))fail('Ca này đã có lượt chấm công. Chọn "Một lượt" để bổ sung lượt còn thiếu.',409);validate_correction(['shift'=>$b['shift'],'type'=>'in','time'=>$in,'reason'=>$b['reason']??null]);$ids=[$a->insertEvent(['shift'=>$b['shift'],'type'=>'in','time'=>$in,'reason'=>$b['reason']],$b['user_id'],true),$a->insertEvent(['shift'=>$b['shift'],'type'=>'out','time'=>$out,'reason'=>$b['reason']],$b['user_id'],true)];return [201,['ok'=>true,'ids'=>$ids]];}
 if($path==='/attendance/manual'&&$method==='POST'){validate_correction($b);if(!is_int($b['user_id']??null))fail('Chọn nhân viên.');$a->target($b['user_id']);$id=$a->insertEvent($b,$b['user_id'],true);return [201,['ok'=>true,'id'=>$id]];}
 return null;
}
function validate_correction(array $b): void {if(!in_array($b['shift']??'', ['day_first','day_second','ot'],true)||!in_array($b['type']??'', ['in','out'],true)||!is_int($b['time']??null)||$b['time']<1577836800000||$b['time']>now_ms()||!is_string($b['reason']??null)||strlen(trim($b['reason']))<10||strlen($b['reason'])>1500)fail('Chọn ca, lượt chấm, giờ không ở tương lai và lý do từ 10–500 ký tự.');}
